prompt:
Find the shortest request sequence of integers from `{1, 2, 3, 4}` (lexicographically first on ties) for which `misses(seq, 3) > misses(seq, 2)`. Report the sequence and `[misses(seq, 2), misses(seq, 3)]`.
```js
function misses(seq, cap) {
  const q = [];
  let m = 0;
  for (const p of seq) {
    const h = q.find(x => x.p === p);
    if (h) { h.r = 1; continue; }
    m++;
    if (q.length === cap) {
      while (q[0].r) { const x = q.shift(); x.r = 0; q.push(x); }
      q.shift();
    }
    q.push({ p, r: 0 });
  }
  return m;
}
```
